    "merged_data['price_peak_var'] = pd.to_numeric(merged_data['price_peak_var'], errors='coerce')\n",
    "merged_data['price_peak_var'] = merged_data.groupby('id')['price_peak_var'].pct_change(fill_method=None).fillna(0)\n",
    "merged_data.replace([np.inf, -np.inf], np.nan, inplace=True)"
